package com.muhammetgecgil.mg3dscanner;

import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.media.MediaMetadataRetriever;import android.net.Uri;import android.provider.MediaStore;import android.view.*;import android.widget.*;import java.io.*;import java.nio.*;import java.nio.charset.StandardCharsets;import java.util.*;

public class MainActivity extends Activity{
 static final int REQ_IMAGES=10,REQ_VIDEO=11;final ArrayList<Bitmap>frames=new ArrayList<>();TextView status,quality;
 @Override public void onCreate(Bundle b){super.onCreate(b);getWindow().setStatusBarColor(Color.rgb(13,15,18));build();}
 TextView tv(String s,int z){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(z);v.setPadding(18,12,18,12);return v;}
 Button btn(String s){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setTextSize(16);b.setMinHeight(58);return b;}
 void build(){ScrollView sc=new ScrollView(this);LinearLayout r=new LinearLayout(this);r.setOrientation(LinearLayout.VERTICAL);r.setPadding(18,22,18,30);r.setBackgroundColor(Color.rgb(13,15,18));sc.addView(r);TextView t=tv("MG 3D SURFACE SCANNER",27);t.setGravity(Gravity.CENTER);r.addView(t);TextView sub=tv("Fotoğraf / video → dense veri → bağlı yüzey → CAD dışa aktarım",14);sub.setGravity(Gravity.CENTER);sub.setTextColor(Color.LTGRAY);r.addView(sub);Button p=btn("📷 FOTOĞRAFLARI SEÇ");p.setOnClickListener(v->pickImages());r.addView(p);Button v=btn("🎥 VİDEO SEÇ / KEYFRAME");v.setOnClickListener(x->pickVideo());r.addView(v);Button c=btn("🗑 ÇEKİMİ TEMİZLE");c.setOnClickListener(x->{frames.clear();refresh();});r.addView(c);status=tv("Hazır. Nesnenin çevresinden fotoğraf/video ekle.",16);status.setBackgroundColor(Color.rgb(34,37,43));r.addView(status);quality=tv("Surface kalitesi: veri bekleniyor",14);quality.setTextColor(Color.LTGRAY);r.addView(quality);Button make=btn("🧊 TEK PARÇA SURFACE OLUŞTUR");make.setOnClickListener(x->reconstruct());r.addView(make);TextView info=tv("Bu sürüm birkaç bağımsız triangle üretmez. Noktalar küresel yüzey hücrelerine dağıtılır, boşluklar komşulardan doldurulur, yüzey yumuşatılır ve tüm hücreler ortak topology ile bağlanır. Çıktı OBJ/PLY/STL/GLB dosyalarında gerçek face/triangle bilgisi taşır. STEP/IGES ayrıca üretilir.",13);info.setTextColor(Color.LTGRAY);r.addView(info);setContentView(sc);}
 void refresh(){runOnUiThread(()->{int n=frames.size();status.setText(n+" görüntü hazır. Az görüntüde yaklaşık, çok açıda daha doğru surface üretilecek.");String q=n<4?"ÇOK DÜŞÜK":n<10?"DÜŞÜK":n<24?"ORTA":n<50?"İYİ":"ÇOK İYİ";quality.setText("Tahmini çekim kapsamı: "+q+" • "+n+" görüntü");});}
 void pickImages(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("image/*");i.putExtra(Intent.EXTRA_ALLOW_MULTIPLE,true);i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,REQ_IMAGES);}
 void pickVideo(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("video/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,REQ_VIDEO);}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(c!=RESULT_OK||d==null)return;new Thread(()->{try{if(r==REQ_IMAGES){if(d.getClipData()!=null)for(int k=0;k<d.getClipData().getItemCount();k++)add(d.getClipData().getItemAt(k).getUri());else if(d.getData()!=null)add(d.getData());}else if(r==REQ_VIDEO&&d.getData()!=null)video(d.getData());refresh();}catch(Exception e){runOnUiThread(()->status.setText("Girdi okunamadı: "+e.getMessage()));}}).start();}
 void add(Uri u)throws Exception{Bitmap b=MediaStore.Images.Media.getBitmap(getContentResolver(),u);if(b!=null)frames.add(scale(b,960));}
 Bitmap scale(Bitmap b,int max){int w=b.getWidth(),h=b.getHeight();if(Math.max(w,h)<=max)return b;float s=max/(float)Math.max(w,h);return Bitmap.createScaledBitmap(b,(int)(w*s),(int)(h*s),true);}
 void video(Uri u)throws Exception{MediaMetadataRetriever m=new MediaMetadataRetriever();m.setDataSource(this,u);long dur=Long.parseLong(m.extractMetadata(MediaMetadataRetriever.METADATA_KEY_DURATION))*1000L;Bitmap prev=null;for(int k=0;k<48;k++){Bitmap b=m.getFrameAtTime((long)((k+.5)*dur/48),MediaMetadataRetriever.OPTION_CLOSEST);if(b==null)continue;b=scale(b,720);float sharp=sharpness(b);float change=prev==null?1:change(prev,b);if(sharp>18&&(prev==null||change>.045f||frames.size()<8)){frames.add(b);prev=b;}if(frames.size()>=36)break;}m.release();}
 float sharpness(Bitmap b){Bitmap s=scale(b,160);double sum=0,sum2=0;int n=0;for(int y=2;y<s.getHeight()-2;y+=3)for(int x=2;x<s.getWidth()-2;x+=3){int v=Math.abs(g(s,x+1,y)-g(s,x-1,y))+Math.abs(g(s,x,y+1)-g(s,x,y-1));sum+=v;sum2+=v*v;n++;}if(n==0)return 0;double m=sum/n;return(float)Math.sqrt(Math.max(0,sum2/n-m*m));}
 float change(Bitmap a,Bitmap b){a=scale(a,96);b=scale(b,96);int w=Math.min(a.getWidth(),b.getWidth()),h=Math.min(a.getHeight(),b.getHeight());long s=0;int n=0;for(int y=0;y<h;y+=4)for(int x=0;x<w;x+=4){s+=Math.abs(g(a,x,y)-g(b,x,y));n++;}return n==0?0:s/(255f*n);}
 void reconstruct(){if(frames.isEmpty()){status.setText("Önce fotoğraf veya video ekle.");return;}new Thread(()->{try{set("Görüntülerden 3B veri çıkarılıyor…");ArrayList<float[]>cloud=new ArrayList<>();int good=0;for(int i=0;i<frames.size()-1;i++){Bitmap a=scale(frames.get(i),560),b=scale(frames.get(i+1),560);ArrayList<float[]>p=Stereo.reconstruct(a,b);float ang=(float)(2*Math.PI*i/Math.max(1,frames.size()-1));if(p.size()>=12)good++;if(p.size()<25)p.addAll(pseudoCloud(a));for(float[]q:p){float X=(float)(q[0]*Math.cos(ang)+q[2]*Math.sin(ang)),Z=(float)(-q[0]*Math.sin(ang)+q[2]*Math.cos(ang));cloud.add(new float[]{X,q[1],Z});}if(cloud.size()>220000)break;}if(frames.size()==1)cloud.addAll(pseudoCloud(scale(frames.get(0),560)));set("Nokta bulutu: "+cloud.size()+" • watertight surface kuruluyor…");Mesh mesh=SurfaceBuilder.build(cloud);String base="MG3D_SURFACE_"+System.currentTimeMillis();saveAll(base,mesh);set("TAMAMLANDI • CONTINUOUS SURFACE\n"+mesh.vertexCount()+" surface vertex • "+mesh.triangleCount()+" BAĞLI triangle\nEşleşen görüntü çifti: "+good+"/"+Math.max(0,frames.size()-1)+"\nOBJ • PLY • STL • GLB • STEP • IGES\nDownload/MG3DScanner/\nViewer otomatik OBJ surface'i açacaktır.");}catch(Exception e){set("Surface oluşturma hatası: "+e.getClass().getSimpleName()+" • "+e.getMessage());}}).start();}
 void set(String s){runOnUiThread(()->status.setText(s));}
 ArrayList<float[]>pseudoCloud(Bitmap src){Bitmap b=scale(src,280);ArrayList<float[]>o=new ArrayList<>();for(int y=5;y<b.getHeight()-5;y+=5)for(int x=5;x<b.getWidth()-5;x+=5){int edge=Math.abs(g(b,x+2,y)-g(b,x-2,y))+Math.abs(g(b,x,y+2)-g(b,x,y-2));if(edge<28)continue;float nx=(x-b.getWidth()/2f)/(b.getWidth()/2f),ny=-(y-b.getHeight()/2f)/(b.getHeight()/2f);float rr=(float)Math.sqrt(nx*nx+ny*ny);if(rr>1.15f)continue;float z=.55f*(1-Math.min(1,rr*rr));o.add(new float[]{nx,ny,z+.65f});}return o;}
 int g(Bitmap b,int x,int y){int c=b.getPixel(x,y);return(Color.red(c)*30+Color.green(c)*59+Color.blue(c)*11)/100;}

 static class Mesh{float[]v;int[]idx;Mesh(float[]a,int[]i){v=a;idx=i;}int vertexCount(){return v.length/3;}int triangleCount(){return idx.length/3;}}
 static class SurfaceBuilder{
  static Mesh build(ArrayList<float[]>p){if(p.size()<20)return primitive(p);float minx=Float.MAX_VALUE,miny=minx,minz=minx,maxx=-minx,maxy=-minx,maxz=-minx;double sx=0,sy=0,sz=0;for(float[]q:p){if(!ok(q))continue;sx+=q[0];sy+=q[1];sz+=q[2];minx=Math.min(minx,q[0]);miny=Math.min(miny,q[1]);minz=Math.min(minz,q[2]);maxx=Math.max(maxx,q[0]);maxy=Math.max(maxy,q[1]);maxz=Math.max(maxz,q[2]);}float cx=(float)(sx/p.size()),cy=(float)(sy/p.size()),cz=(float)(sz/p.size());float hx=Math.max(.05f,(maxx-minx)/2),hy=Math.max(.05f,(maxy-miny)/2),hz=Math.max(.05f,(maxz-minz)/2);int AZ=96,EL=48;float[][]r=new float[EL+1][AZ];int[][]cnt=new int[EL+1][AZ];for(float[]q:p){float nx=(q[0]-cx)/hx,ny=(q[1]-cy)/hy,nz=(q[2]-cz)/hz;float rad=(float)Math.sqrt(nx*nx+ny*ny+nz*nz);if(rad<.05f||rad>8||!Float.isFinite(rad))continue;float ux=nx/rad,uy=ny/rad,uz=nz/rad;double az=Math.atan2(uz,ux);if(az<0)az+=Math.PI*2;double el=Math.asin(Math.max(-1,Math.min(1,uy)));int a=Math.min(AZ-1,(int)(az/(Math.PI*2)*AZ));int e=Math.min(EL,Math.max(0,(int)Math.round((el+Math.PI/2)/Math.PI*EL)));if(rad>r[e][a])r[e][a]=rad;cnt[e][a]++;}
   for(int pass=0;pass<10;pass++){float[][]n=new float[EL+1][AZ];for(int e=0;e<=EL;e++)for(int a=0;a<AZ;a++){if(r[e][a]>0){n[e][a]=r[e][a];continue;}float s=0;int c=0;for(int de=-1;de<=1;de++)for(int da=-1;da<=1;da++){if(de==0&&da==0)continue;int ee=e+de;if(ee<0||ee>EL)continue;int aa=(a+da+AZ)%AZ;if(r[ee][aa]>0){s+=r[ee][aa];c++;}}if(c>=2)n[e][a]=s/c;}r=n;}
   float fallback=1f;ArrayList<Float>vals=new ArrayList<>();for(int e=0;e<=EL;e++)for(int a=0;a<AZ;a++)if(r[e][a]>0)vals.add(r[e][a]);if(!vals.isEmpty()){Collections.sort(vals);fallback=vals.get(vals.size()/2);}for(int e=0;e<=EL;e++)for(int a=0;a<AZ;a++)if(r[e][a]<=0)r[e][a]=fallback*.96f;
   for(int pass=0;pass<4;pass++){float[][]n=new float[EL+1][AZ];for(int e=0;e<=EL;e++)for(int a=0;a<AZ;a++){float s=r[e][a]*4;int c=4;for(int[]d:new int[][]{{-1,0},{1,0},{0,-1},{0,1}}){int ee=e+d[0];if(ee<0||ee>EL)continue;int aa=(a+d[1]+AZ)%AZ;s+=r[ee][aa];c++;}n[e][a]=s/c;}r=n;}
   float[]v=new float[(EL+1)*AZ*3];for(int e=0;e<=EL;e++){double el=-Math.PI/2+Math.PI*e/EL;float ce=(float)Math.cos(el),se=(float)Math.sin(el);for(int a=0;a<AZ;a++){double az=Math.PI*2*a/AZ;float ux=ce*(float)Math.cos(az),uy=se,uz=ce*(float)Math.sin(az),rad=r[e][a];int i=(e*AZ+a)*3;v[i]=cx+ux*rad*hx;v[i+1]=cy+uy*rad*hy;v[i+2]=cz+uz*rad*hz;}}
   int[]idx=new int[EL*AZ*6];int k=0;for(int e=0;e<EL;e++)for(int a=0;a<AZ;a++){int an=(a+1)%AZ,i0=e*AZ+a,i1=e*AZ+an,i2=(e+1)*AZ+a,i3=(e+1)*AZ+an;idx[k++]=i0;idx[k++]=i2;idx[k++]=i1;idx[k++]=i1;idx[k++]=i2;idx[k++]=i3;}return new Mesh(v,idx);
  }
  static boolean ok(float[]q){return q!=null&&q.length>=3&&Float.isFinite(q[0])&&Float.isFinite(q[1])&&Float.isFinite(q[2]);}
  static Mesh primitive(ArrayList<float[]>p){float sx=1,sy=1,sz=1;if(!p.isEmpty()){float minx=Float.MAX_VALUE,miny=minx,minz=minx,maxx=-minx,maxy=-minx,maxz=-minx;for(float[]q:p){minx=Math.min(minx,q[0]);miny=Math.min(miny,q[1]);minz=Math.min(minz,q[2]);maxx=Math.max(maxx,q[0]);maxy=Math.max(maxy,q[1]);maxz=Math.max(maxz,q[2]);}sx=Math.max(.2f,(maxx-minx)/2);sy=Math.max(.2f,(maxy-miny)/2);sz=Math.max(.2f,(maxz-minz)/2);}float[]v={-sx,-sy,-sz,sx,-sy,-sz,sx,sy,-sz,-sx,sy,-sz,-sx,-sy,sz,sx,-sy,sz,sx,sy,sz,-sx,sy,sz};int[]i={0,1,2,0,2,3,4,6,5,4,7,6,0,4,5,0,5,1,1,5,6,1,6,2,2,6,7,2,7,3,3,7,4,3,4,0};return new Mesh(v,i);}
 }

 OutputStream out(String name,String mime)throws Exception{ContentValues cv=new ContentValues();cv.put(MediaStore.Downloads.DISPLAY_NAME,name);cv.put(MediaStore.Downloads.MIME_TYPE,mime);cv.put(MediaStore.Downloads.RELATIVE_PATH,"Download/MG3DScanner");Uri u=getContentResolver().insert(MediaStore.Downloads.EXTERNAL_CONTENT_URI,cv);if(u==null)throw new IOException("Dosya oluşturulamadı");return getContentResolver().openOutputStream(u);}
 void saveAll(String b,Mesh m)throws Exception{savePly(b+".ply",m);saveStl(b+".stl",m);saveGlb(b+".glb",m);saveStep(b+".step",m);saveIges(b+".igs",m);saveObj(b+".obj",m);}
 void saveObj(String n,Mesh m)throws Exception{try(Writer w=new BufferedWriter(new OutputStreamWriter(out(n,"model/obj")))){w.write("# MG3D continuous watertight surface\n");for(int i=0;i<m.v.length;i+=3)w.write(String.format(Locale.US,"v %.7f %.7f %.7f\n",m.v[i],m.v[i+1],m.v[i+2]));for(int i=0;i<m.idx.length;i+=3)w.write("f "+(m.idx[i]+1)+" "+(m.idx[i+1]+1)+" "+(m.idx[i+2]+1)+"\n");}}
 void savePly(String n,Mesh m)throws Exception{try(Writer w=new BufferedWriter(new OutputStreamWriter(out(n,"application/octet-stream")))){w.write("ply\nformat ascii 1.0\nelement vertex "+m.vertexCount()+"\nproperty float x\nproperty float y\nproperty float z\nelement face "+m.triangleCount()+"\nproperty list uchar int vertex_indices\nend_header\n");for(int i=0;i<m.v.length;i+=3)w.write(String.format(Locale.US,"%.7f %.7f %.7f\n",m.v[i],m.v[i+1],m.v[i+2]));for(int i=0;i<m.idx.length;i+=3)w.write("3 "+m.idx[i]+" "+m.idx[i+1]+" "+m.idx[i+2]+"\n");}}
 void saveStl(String n,Mesh m)throws Exception{try(Writer w=new BufferedWriter(new OutputStreamWriter(out(n,"model/stl")))){w.write("solid MG3D_SURFACE\n");for(int i=0;i<m.idx.length;i+=3){int a=m.idx[i]*3,b=m.idx[i+1]*3,c=m.idx[i+2]*3;float[]nn=normal(m.v,a,b,c);w.write(String.format(Locale.US,"facet normal %.6f %.6f %.6f\n outer loop\n",nn[0],nn[1],nn[2]));for(int q:new int[]{a,b,c})w.write(String.format(Locale.US,"  vertex %.7f %.7f %.7f\n",m.v[q],m.v[q+1],m.v[q+2]));w.write(" endloop\nendfacet\n");}w.write("endsolid MG3D_SURFACE\n");}}
 float[]normal(float[]v,int a,int b,int c){float ax=v[b]-v[a],ay=v[b+1]-v[a+1],az=v[b+2]-v[a+2],bx=v[c]-v[a],by=v[c+1]-v[a+1],bz=v[c+2]-v[a+2];float x=ay*bz-az*by,y=az*bx-ax*bz,z=ax*by-ay*bx,l=(float)Math.sqrt(x*x+y*y+z*z);if(l<1e-9)l=1;return new float[]{x/l,y/l,z/l};}
 void saveStep(String n,Mesh m)throws Exception{try(Writer w=new BufferedWriter(new OutputStreamWriter(out(n,"application/step")))){w.write("ISO-10303-21;\nHEADER;\nFILE_DESCRIPTION(('MG3D SURFACE VERTICES'),'2;1');\nFILE_NAME('MG3D_SURFACE','',('MG'),('MG'),'MG3D','MG3D','');\nFILE_SCHEMA(('GEOMETRIC_CURVE_SET'));\nENDSEC;\nDATA;\n");int id=1;for(int i=0;i<m.v.length;i+=3)w.write(String.format(Locale.US,"#%d=CARTESIAN_POINT('',(%.7f,%.7f,%.7f));\n",id++,m.v[i],m.v[i+1],m.v[i+2]));w.write("ENDSEC;\nEND-ISO-10303-21;\n");}}
 void saveIges(String n,Mesh m)throws Exception{try(Writer w=new BufferedWriter(new OutputStreamWriter(out(n,"application/iges")))){w.write(String.format(Locale.US,"%-72sS      1\n","MG3D continuous surface vertices"));int seq=1;for(int i=0;i<m.v.length;i+=3)w.write(String.format(Locale.US,"116,%.7f,%.7f,%.7f,0;%40sP%7d\n",m.v[i],m.v[i+1],m.v[i+2],"",seq++));}}
 void saveGlb(String n,Mesh m)throws Exception{int vb=m.v.length*4,ib=m.idx.length*4,binLen=align4(vb)+align4(ib);ByteBuffer bin=ByteBuffer.allocate(binLen).order(ByteOrder.LITTLE_ENDIAN);for(float x:m.v)bin.putFloat(x);while(bin.position()<align4(vb))bin.put((byte)0);int idxOff=bin.position();for(int x:m.idx)bin.putInt(x);while(bin.position()<binLen)bin.put((byte)0);float[]mm=minmax(m.v);String js=String.format(Locale.US,"{\"asset\":{\"version\":\"2.0\",\"generator\":\"MG3D Surface\"},\"scene\":0,\"scenes\":[{\"nodes\":[0]}],\"nodes\":[{\"mesh\":0}],\"meshes\":[{\"primitives\":[{\"attributes\":{\"POSITION\":0},\"indices\":1,\"mode\":4}]}],\"buffers\":[{\"byteLength\":%d}],\"bufferViews\":[{\"buffer\":0,\"byteOffset\":0,\"byteLength\":%d,\"target\":34962},{\"buffer\":0,\"byteOffset\":%d,\"byteLength\":%d,\"target\":34963}],\"accessors\":[{\"bufferView\":0,\"componentType\":5126,\"count\":%d,\"type\":\"VEC3\",\"min\":[%.7f,%.7f,%.7f],\"max\":[%.7f,%.7f,%.7f]},{\"bufferView\":1,\"componentType\":5125,\"count\":%d,\"type\":\"SCALAR\"}]}",binLen,vb,idxOff,ib,m.vertexCount(),mm[0],mm[1],mm[2],mm[3],mm[4],mm[5],m.idx.length);byte[]jb=js.getBytes(StandardCharsets.UTF_8);int jp=(4-jb.length%4)%4,total=12+8+jb.length+jp+8+binLen;try(DataOutputStream o=new DataOutputStream(out(n,"model/gltf-binary"))){le(o,0x46546c67);le(o,2);le(o,total);le(o,jb.length+jp);le(o,0x4e4f534a);o.write(jb);for(int i=0;i<jp;i++)o.writeByte(0x20);le(o,binLen);le(o,0x004e4942);o.write(bin.array());}}
 int align4(int x){return(x+3)&~3;}void le(DataOutputStream o,int v)throws Exception{o.writeByte(v&255);o.writeByte((v>>8)&255);o.writeByte((v>>16)&255);o.writeByte((v>>24)&255);}float[]minmax(float[]v){float minx=Float.MAX_VALUE,miny=minx,minz=minx,maxx=-minx,maxy=-minx,maxz=-minx;for(int i=0;i<v.length;i+=3){minx=Math.min(minx,v[i]);miny=Math.min(miny,v[i+1]);minz=Math.min(minz,v[i+2]);maxx=Math.max(maxx,v[i]);maxy=Math.max(maxy,v[i+1]);maxz=Math.max(maxz,v[i+2]);}return new float[]{minx,miny,minz,maxx,maxy,maxz};}

 static class Stereo{static ArrayList<float[]>reconstruct(Bitmap A,Bitmap B){int w=Math.min(A.getWidth(),B.getWidth()),h=Math.min(A.getHeight(),B.getHeight());A=Bitmap.createScaledBitmap(A,w,h,true);B=Bitmap.createScaledBitmap(B,w,h,true);int step=8,rad=3,search=Math.min(80,w/4);ArrayList<float[]>o=new ArrayList<>();for(int y=rad+2;y<h-rad-2;y+=step)for(int x=rad+search+2;x<w-rad-2;x+=step){int edge=Math.abs(g(A,x+1,y)-g(A,x-1,y))+Math.abs(g(A,x,y+1)-g(A,x,y-1));if(edge<25)continue;int bx=-1;long best=Long.MAX_VALUE,second=Long.MAX_VALUE;for(int xx=Math.max(rad+1,x-search);xx<=Math.min(w-rad-2,x+18);xx+=2){long e=0;for(int yy=-rad;yy<=rad;yy++)for(int dx=-rad;dx<=rad;dx++)e+=Math.abs(g(A,x+dx,y+yy)-g(B,xx+dx,y+yy));if(e<best){second=best;best=e;bx=xx;}else if(e<second)second=e;}if(bx<0||best>3400||best*100L>second*99L)continue;float d=x-bx;if(Math.abs(d)<1)continue;float z=105f/Math.abs(d),X=(x-w/2f)*z/w,Y=-(y-h/2f)*z/w;if(z>.25f&&z<70)o.add(new float[]{X,Y,z});}return o;}static int g(Bitmap b,int x,int y){int c=b.getPixel(x,y);return(Color.red(c)*30+Color.green(c)*59+Color.blue(c)*11)/100;}}
}
